'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var defaults = require( './../defaults.js' );
var resolveValue = require( './resolve_value.js' );
var resolveTextValue = require( './resolve_text_value.js' );
var resolveSchemaValue = require( './resolve_schema_value.js' );


// VARIABLES //

var PROPS = [
	'aria',
	'bandPosition',
	'description',
	'domain',
	'domainCap',
	'domainColor',
	'domainDashOffset',
	'domainOpacity',
	'domainWidth',
	'grid',
	'gridCap',
	'gridColor',
	'gridDashOffset',
	'gridOpacity',
	'labelAlign',
	'labelAngle',
	'labelBaseline',
	'labelBound',
	'labelColor',
	'labelFlush',
	'labelFlushOffset',
	'labelFont',
	'labelFontSize',
	'labelFontStyle',
	'labelFontWeight',
	'labelLimit',
	'labelLineHeight',
	'labelOffset',
	'labelOpacity',
	'labelOverlap',
	'labelPadding',
	'labels',
	'labelSeparation',
	'maxExtent',
	'minExtent',
	'offset',
	'orient',
	'position',
	'tickBand',
	'tickCap',
	'tickColor',
	'tickDashOffset',
	'tickMinStep',
	'tickOffset',
	'tickOpacity',
	'ticks',
	'tickSize',
	'tickWidth',
	'titleAlign',
	'titleAnchor',
	'titleAngle',
	'titleBaseline',
	'titleColor',
	'titleFont',
	'titleFontSize',
	'titleFontStyle',
	'titleFontWeight',
	'titleLimit',
	'titleLineHeight',
	'titleOpacity',
	'titlePadding',
	'titleX',
	'titleY',
	'zindex'
];
var ARRAY_PROPS = [
	'domainDash',
	'gridDash',
	'tickDash',
	'tickCount'
];
var SCHEMA_PROPS = [
	'gridScale',
	'scale'
];
var TEXT_PROPS = [
	'title'
];


// MAIN //

/**
* Synchronizes an axis editor configuration with a provided schema.
*
* @private
* @param {Object} conf - axis configuration object
* @param {Object} schema - axis schema
* @returns {Object} mutated configuration object
*/
function config( conf, schema ) {
	var def;
	var i;

	def = defaults.axis;

	for ( i = 0; i < TEXT_PROPS.length; i++ ) {
		resolveTextValue( schema, def, conf, TEXT_PROPS[ i ] );
	}
	for ( i = 0; i < ARRAY_PROPS.length; i++ ) {
		resolveValue( schema, def, conf, ARRAY_PROPS[ i ] );
		if ( isArray( conf[ ARRAY_PROPS[ i ] ] ) ) {
			conf[ ARRAY_PROPS[ i ] ] = conf[ ARRAY_PROPS[ i ] ].join( ', ' );
		}
	}
	for ( i = 0; i < PROPS.length; i++ ) {
		resolveValue( schema, def, conf, PROPS[ i ] );
	}
	// Convert `labelBound` from a boolean to a string so that lil-gui renders a text input instead of a checkbox:
	if ( conf.labelBound === false ) {
		conf.labelBound = '';
	}
	for ( i = 0; i < SCHEMA_PROPS.length; i++ ) {
		resolveSchemaValue( schema, def, conf, SCHEMA_PROPS[ i ] );
	}
	return conf;
}


// EXPORTS //

module.exports = config;
